INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6744226, 1007928, 130483, '<td valign="top">I would love to know how you did this.  It is so very well done!  Congratulations.</td>', 'I would love to know how you did this.  It is so very well done!  Congratulations.', '2012-04-17 06:49:45.000000', NULL, 0),
(6744238, 1008244, 113278, '<td valign="top">Nice image and congrats on the tt</td>', 'Nice image and congrats on the tt', '2012-04-17 07:53:34.000000', NULL, 0),
(6744292, 1008424, 15711, '<td valign="top">Congrats.  You can never go wrong with tulips. :)</td>', 'Congrats.  You can never go wrong with tulips. :)', '2012-04-17 09:49:01.000000', NULL, 0),
(6744353, 1008424, 43463, '<td valign="top">The lighting on these tulips is just spectacular - creates just the right balance of shadows and highlights to make the textures and color of the flower pop visually. The spread of flowers just fills the composition allowing us to drink in the beauty of this floral bouquet. This was one of my 10''s. Congrats on the Blue Allen! <br/><br/><i>Message edited by author 2012-04-17 10:44:18.</i></td>', 'The lighting on these tulips is just spectacular - creates just the right balance of shadows and highlights to make the textures and color of the flower pop visually. The spread of flowers just fills the composition allowing us to drink in the beauty of this floral bouquet. This was one of my 10''s. Congrats on the Blue Allen! ', '2012-04-17 10:47:36.000000', '2012-04-17 11:44:18.000000', 0),
(6744358, 1008424, 140305, '<td valign="top">Goregeous shot! Congrats on the ribbon.</td>', 'Goregeous shot! Congrats on the ribbon.', '2012-04-17 10:58:10.000000', NULL, 0),
(6744362, 1008122, 140305, '<td valign="top">Beautiful job. Congratulations on the ribbon.</td>', 'Beautiful job. Congratulations on the ribbon.', '2012-04-17 10:59:27.000000', NULL, 0),
(6744363, 1008706, 43463, '<td valign="top">Congrats on the top 10 finish. I loved this composition and I am quite surprised you did not finish much higher and above me. The colors, the arrangement of elements, the lighting and above all the textures &amp; shapes is what made this shot so very appealing. This was one of the my few 10''s in this challenge. A few of the arrangements in this challenge had the ''traditional'' composition of elements. Not a complaint, just an observation: looking back at <i>some</i> of the other Still Life Challenges it *appears* that the ''less is more'' composition rates higher than the ''stick to traditional method''.</td>', 'Congrats on the top 10 finish. I loved this composition and I am quite surprised you did not finish much higher and above me. The colors, the arrangement of elements, the lighting and above all the textures & shapes is what made this shot so very appealing. This was one of the my few 10''s in this challenge. A few of the arrangements in this challenge had the ''traditional'' composition of elements. Not a complaint, just an observation: looking back at some of the other Still Life Challenges it *appears* that the ''less is more'' composition rates higher than the ''stick to traditional method''.', '2012-04-17 10:59:40.000000', NULL, 0),
(6744367, 1007928, 140305, '<td valign="top">Congrats on the ribbon. This is such an interesting shot!</td>', 'Congrats on the ribbon. This is such an interesting shot!', '2012-04-17 11:03:58.000000', NULL, 0),
(6744369, 1008742, 43463, '<td valign="top">Grats on finishing in the top 15%! I have to say that as time went by this grew in appeal more and more. It eventually won me over to reward it with one of the few 10''s I passed out. Initially, I found the angle an odd choice to present the still life - looking straight down. But it was the looking straight down that allowed the elements within the composition to shine. My eyes took in the textures/grain of the wood slats to the weave of the circular basket to the tactile skin of the lemons. The shapes are what also caught and held my attention; the circle of the basket, the heart shape, the squares throughout with the table, and the oval of the lemons.</td>', 'Grats on finishing in the top 15%! I have to say that as time went by this grew in appeal more and more. It eventually won me over to reward it with one of the few 10''s I passed out. Initially, I found the angle an odd choice to present the still life - looking straight down. But it was the looking straight down that allowed the elements within the composition to shine. My eyes took in the textures/grain of the wood slats to the weave of the circular basket to the tactile skin of the lemons. The shapes are what also caught and held my attention; the circle of the basket, the heart shape, the squares throughout with the table, and the oval of the lemons.', '2012-04-17 11:10:08.000000', NULL, 0),
(6744393, 1008122, 43463, '<td valign="top">Congrats on the Red Ribbon! Heh, symmetry - your second entry and you won 2nd place:-) Beautiful lighting on your subjects that brings out all the warm tones of the yellows that is very appealing to the eye. The arrangement of objects is also very appealing. You have the height going up from low to high in the left to right, but there is also the subtle touch of low to high and back down that appears in the composition. The eye travels from the left following the rising levels of the liquid in the containers. By the time we get to the far right the liquid level fall back down again which is a nice smooth transition path for the eye to travel from the bottle to the tipped over glass that rests near to it.</td>', 'Congrats on the Red Ribbon! Heh, symmetry - your second entry and you won 2nd place:-) Beautiful lighting on your subjects that brings out all the warm tones of the yellows that is very appealing to the eye. The arrangement of objects is also very appealing. You have the height going up from low to high in the left to right, but there is also the subtle touch of low to high and back down that appears in the composition. The eye travels from the left following the rising levels of the liquid in the containers. By the time we get to the far right the liquid level fall back down again which is a nice smooth transition path for the eye to travel from the bottle to the tipped over glass that rests near to it.', '2012-04-17 11:29:22.000000', NULL, 0),
(6744653, 1009005, 94815, '<td valign="top">Nice finish Brent.</td>', 'Nice finish Brent.', '2012-04-17 17:49:20.000000', NULL, 0),
(6744655, 1008350, 94815, '<td valign="top">Nice mix of colors Carole esp the non-yellow ones.</td>', 'Nice mix of colors Carole esp the non-yellow ones.', '2012-04-17 17:52:26.000000', NULL, 0),
